			"summary":"<download|Downloads> a file from an Internet <server> asynchronously via\nFTP, HTTP or HTTPS",
			"introduced":"2.0",
			"OS":["mac","windows","linux","ios","android","html5"],
			"platforms":["desktop","server","mobile"],
