			"id":"script-714",
			"name":"measuretext",
			"display name":"measureText",
			"library":"script",
			"type":"function",
			"syntax":[
				"measureText(<text>,<objectReference>,[<mode>])"
			],
			"display syntax":[
				"measureText(<i>text</i>,<i>objectReference</i>,[<i>mode</i>])"
			],
			"summary":"<return|Returns> the width, size or bounds of the text drawn with the\neffective font attribute of the given object.",
			"introduced":"6.5",
			"OS":["mac","windows","linux","ios","android"],
			"platforms":["desktop","server","mobile"],
			"parameters":[{
				"name":"text",
				"type":"string",
				"refparam":"false",
				"description":"Any text string, or an <expression> that <evaluate|evaluates> to \na string."
			},{
				"name":"objectReference",
				"type":"string",
				"refparam":"false",
				"description":"An expression that <evaluate|evaluates> to an object reference."
			},{
				"name":"mode",
				"type":"enum",
				"refparam":"false",
				"description":"",
				
				"enum":[
					{"value":"\"width\"",
					"description":"(default if not specified)"},
					{"value":"\"size\"",
					"description":""},
					{"value":"\"bounds\"",
					"description":""}]
			}],
			"examples":[{
				"script":"local tText, tTextWidth\nput \"Hello world\" into tText\nput measureText(tText,field \"myField\") into tTextWidth"
			},{
				"script":"local tText, tTextSize\nput \"Hello world\" into field \"someField\"\nput field \"someField\" into tText\nput measureText(tText,field \"someField\",\"size\") into tTextSize"
			},{
				"script":"# handler in a field\non textChanged\n  local tTextBounds\n  put measureText(\"foo\",me,\"bounds\") into tTextBounds\n  put \"The text in this field has these bounds: \" & tTextBounds\nend textChanged"
			}],
			"value":[{
				"name":"return",
				"type":"",
				"description":"-   width (number): the width of the text\n-   size (int,int): the width and height of the text as a \ncomma-separated list; e.g. width,height\n-   bounds (rect): a rectangle identifying the bounds of the text in the\nform `0,-ascent,width,descent` where ascent and descent are relative to\na 0 baseline the text is drawn on."
			}],
			"description":"Use the <measureText> <function> to find the dimensions of the given \ntext if drawn using the effective font attributes of the object \nspecified in the <objectReference> parameter.",
			"references":{
				"property":["formattedWidth","formattedHeight"],
				"message":["textChanged"],
				"glossary":["return","expression","evaluate"],
				"control structure":["function"]
			},
