				"refparam":"false",
				"description":"the name of a purchase request property.\n",
				
				"enum":[
					{"value":"\"quantity\"",
					"description":"The number of items purchased."},
					{"value":"\"productID\"",
					"description":"The identifier of the purchased product."},
					{"value":"\"purchaseDate\"",
					"description":"The date the purchase or restore request was sent."},
					{"value":"\"transactionIdentifier\"",
					"description":"The unique identifier of a successful purchase or restore."},
					{"value":"\"receipt\"",
					"description":"A block of data that can be used to confirm the purchase from a remote server with the iTunes store."},
					{"value":"\"originalPurchaseDate\"",
					"description":"For restored purchases only, the date of the original purchase."},
					{"value":"\"originalTransactionIdentifier\"",
					"description":"For restored purchases only, the transaction identifier of the original purchase."},
					{"value":"\"originalReceipt\"",
					"description":"For restored purchases only, the receipt of the original purchase."}]
