			"associations":["button"],
			"summary":"Specifies whether a <button(object)|button's> background is filled with\nthe <hiliteColor> and <hilitePattern> when the <button(keyword)> is\n<highlight|highlighted>. ",
			"introduced":"1.0",
			"OS":["mac","windows","linux","ios","android"],
