			"syntax":[
				"set the looping of <player> to {true | false}"
			],
			"display syntax":[
				"set the looping of <i>player</i> to {true | false}"
			],
			"associations":["player"],
			"summary":"Specifies whether a movie or sound stops at the end, or restarts from\nthe beginning.",
			"introduced":"1.0",
			"OS":["mac","windows","linux","ios","android"],
			"platforms":["desktop","server","mobile"],
