			"associations":["field","button"],
			"summary":"Specifies the text in a <field>, represented as <Unicode> (double-byte\ncharacters). ",
			"introduced":"2.0",
			"deprecated":"7.0",
			"OS":["mac","windows","linux","ios","android"],
